"use client";

import { useCallback, useMemo, useState } from "react";
import { motion } from "framer-motion";
import {
  ChartFrame,
  areaPath,
  linePath,
  type AxisSpec,
  type ChartContext,
  type ChartPoint,
  type Curve,
  type Pt,
  type SeriesSpec,
} from "@/components/ui/ChartFrame";

/* ------------------------------------------------------------------ *
 * Stacking
 *
 * A stream graph is not a second component. It is a stacked area whose
 * baseline is allowed to float instead of sitting on zero, so the whole
 * thing is one `offset` prop over one stacking pass.
 * ------------------------------------------------------------------ */

export type AreaOffset = "none" | "stacked" | "wiggle";

/**
 * Stacking order is a real editorial choice, not a detail.
 *
 * `given` keeps the caller's order. `descending` puts the largest series
 * on the bottom, where the flattest baseline makes it easiest to read.
 * `insideOut` is the stream graph convention: series are ordered by where
 * they peak and then dealt alternately to the top and bottom of the
 * stack, which buries the volatile ones in the middle and leaves the
 * silhouette calm. The series on the bottom of a stack is the only one
 * anybody can read accurately, so which series that is changes what the
 * chart says.
 */
export type StackOrder = "given" | "descending" | "insideOut";

export interface Band {
  id: string;
  /** Lower and upper edge per column, in domain units. */
  y0: number[];
  y1: number[];
  /** Columns this series actually reported, for the `none` offset's gaps. */
  present: boolean[];
}

function orderIds(ids: string[], heights: Record<string, number[]>, order: StackOrder): string[] {
  if (order === "given") return ids;
  const total = (id: string) => heights[id].reduce((a, b) => a + b, 0);
  if (order === "descending") return [...ids].sort((a, b) => total(b) - total(a));

  const peak = (id: string) => {
    let best = 0;
    let at = 0;
    heights[id].forEach((v, i) => {
      if (v > best) { best = v; at = i; }
    });
    return at;
  };
  const byPeak = [...ids].sort((a, b) => peak(a) - peak(b));
  const top: string[] = [];
  const bottom: string[] = [];
  let topSum = 0;
  let bottomSum = 0;
  for (const id of byPeak) {
    if (topSum < bottomSum) { topSum += total(id); top.push(id); }
    else { bottomSum += total(id); bottom.push(id); }
  }
  return [...bottom.reverse(), ...top];
}

export function stackBands(
  points: ChartPoint[],
  ids: string[],
  offset: AreaOffset,
  order: StackOrder,
): { bands: Band[]; extent: [number, number] } {
  const m = points.length;
  const heights: Record<string, number[]> = {};
  const present: Record<string, boolean[]> = {};
  for (const id of ids) {
    heights[id] = points.map((p) => {
      const v = p.values[id];
      return typeof v === "number" && Number.isFinite(v) ? v : 0;
    });
    present[id] = points.map((p) => typeof p.values[id] === "number");
  }

  if (offset === "none") {
    const bands = ids.map((id) => ({
      id,
      y0: new Array(m).fill(0),
      y1: heights[id],
      present: present[id],
    }));
    let lo = 0;
    let hi = 0;
    for (const id of ids) for (let j = 0; j < m; j++) {
      if (!present[id][j]) continue;
      lo = Math.min(lo, heights[id][j]);
      hi = Math.max(hi, heights[id][j]);
    }
    return { bands, extent: [lo, hi] };
  }

  const stackOrder = orderIds(ids, heights, order);

  // The floating baseline. d3's wiggle offset: at every column, shift the
  // whole stack by the amount that minimises the weighted change in slope
  // across all bands, which is what stops a stream graph from thrashing.
  const base = new Array(m).fill(0);
  if (offset === "wiggle") {
    let y = 0;
    for (let j = 1; j < m; j++) {
      let s1 = 0;
      let s2 = 0;
      for (let i = 0; i < stackOrder.length; i++) {
        const hi = heights[stackOrder[i]];
        let s3 = (hi[j] - hi[j - 1]) / 2;
        for (let k = 0; k < i; k++) {
          const hk = heights[stackOrder[k]];
          s3 += hk[j] - hk[j - 1];
        }
        s1 += hi[j];
        s2 += s3 * hi[j];
      }
      if (s1) y -= s2 / s1;
      base[j] = y;
    }
  }

  const cursor = [...base];
  const byId = new Map<string, Band>();
  for (const id of stackOrder) {
    const y0 = [...cursor];
    const y1 = cursor.map((c, j) => c + heights[id][j]);
    for (let j = 0; j < m; j++) cursor[j] = y1[j];
    byId.set(id, { id, y0, y1, present: present[id] });
  }

  let lo = Infinity;
  let hi = -Infinity;
  for (let j = 0; j < m; j++) {
    lo = Math.min(lo, base[j]);
    hi = Math.max(hi, cursor[j]);
  }
  if (!Number.isFinite(lo)) { lo = 0; hi = 1; }

  // Returned in the caller's order so colours stay pinned to series, not
  // to stack position: reordering the stack must not recolour the chart.
  return { bands: ids.map((id) => byId.get(id)!), extent: [lo, hi] };
}

/* ------------------------------------------------------------------ *
 * Component
 * ------------------------------------------------------------------ */

export interface AreaChartProps {
  data: ChartPoint[];
  series: SeriesSpec[];
  label: string;
  summary?: string;
  offset?: AreaOffset;
  order?: StackOrder;
  /** `spline` is monotone cubic, so a band cannot bulge past its own data. */
  curve?: Extract<Curve, "linear" | "spline">;
  x?: AxisSpec;
  y?: AxisSpec;
  height?: number;
  legend?: boolean;
  formatValue?: (v: number) => string;
  className?: string;
}

export function AreaChart({
  data,
  series,
  label,
  summary,
  offset = "stacked",
  order = "given",
  curve = "linear",
  x,
  y,
  height = 260,
  legend = true,
  formatValue,
  className,
}: AreaChartProps) {
  const isBand = data.length > 0 && typeof data[0].x === "string";

  const yExtent = useCallback(
    (visibleIds: string[], points: ChartPoint[]) => stackBands(points, visibleIds, offset, order).extent,
    [offset, order],
  );

  const draw = (ctx: ChartContext) => {
    const ids = ctx.series.map((s) => s.id);
    const { bands } = stackBands(ctx.points, ids, offset, order);
    const xs = ctx.points.map((p, i) => ctx.px(p, i));

    return (
      <>
        <defs>
          {/* One wipe drives every band, so the stack is revealed as a
              single object rather than as N racing shapes. */}
          <clipPath id={`ac-wipe-${ctx.uid}`}>
            <motion.rect
              x={0}
              y={0}
              height={ctx.height}
              initial={ctx.reduceMotion ? false : { width: 0 }}
              animate={ctx.inView ? { width: ctx.width } : undefined}
              transition={{ duration: 0.95, ease: [0.22, 1, 0.36, 1] }}
            />
          </clipPath>
          {/* Overlaid areas have to be translucent, because reading one
              through another is the whole mode. Stacked bands must not be:
              alpha there lets the gridlines show through the data and lets
              two adjacent bands blend into a third colour that is not in
              the legend. So the gradient is a fade to alpha in `none` and a
              flat opaque fill everywhere else. */}
          {offset === "none" &&
            bands.map((b) => (
              <linearGradient key={b.id} id={`ac-fill-${ctx.uid}-${b.id}`} x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor={ctx.color(b.id)} stopOpacity={0.32} />
                <stop offset="100%" stopColor={ctx.color(b.id)} stopOpacity={0.04} />
              </linearGradient>
            ))}
        </defs>

        <g clipPath={`url(#ac-wipe-${ctx.uid})`}>
          {bands.map((b) => {
            // In the overlaid mode a null is a real hole, so the series is
            // split at its gaps. Stacking cannot do that: a hole would drop
            // every band above it, so there a missing reading contributes
            // zero and the band pinches shut, which is the honest picture
            // of "nothing came in" without tearing the stack.
            const runs: number[][] = [];
            let run: number[] = [];
            for (let j = 0; j < ctx.points.length; j++) {
              if (offset === "none" && !b.present[j]) {
                if (run.length) runs.push(run);
                run = [];
                continue;
              }
              run.push(j);
            }
            if (run.length) runs.push(run);

            return runs.map((cols, ri) => {
              if (cols.length < 2) return null;
              const top: Pt[] = cols.map((j) => ({ x: xs[j], y: ctx.y.at(b.y1[j]) }));
              const bottom: Pt[] = cols.map((j) => ({ x: xs[j], y: ctx.y.at(b.y0[j]) }));
              return (
                <g key={`${b.id}-${ri}`}>
                  <path
                    d={areaPath(top, bottom, curve)}
                    fill={offset === "none" ? `url(#ac-fill-${ctx.uid}-${b.id})` : ctx.color(b.id)}
                  />
                  {/* A hairline on the upper edge keeps two adjacent bands
                      of similar lightness from reading as one shape. */}
                  <path
                    d={linePath(top, curve)}
                    fill="none"
                    stroke={offset === "none" ? ctx.color(b.id) : "var(--cf-dot-ring)"}
                    strokeDasharray={ctx.dash(b.id)}
                    strokeWidth={offset === "none" ? 2 : 1}
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeOpacity={offset === "none" ? 1 : 0.55}
                  />
                </g>
              );
            });
          })}
        </g>
      </>
    );
  };

  return (
    <ChartFrame
      label={label}
      summary={summary}
      series={series}
      points={data}
      height={height}
      legend={legend}
      formatValue={formatValue}
      className={className}
      yExtent={yExtent}
      x={isBand ? { categories: data.map((p) => String(p.x)), ...x } : x}
      // A stream graph's baseline floats, so the y position of a band is an
      // artefact of the layout rather than a value. Labelling that axis
      // would invite a reading the chart cannot support.
      y={offset === "wiggle" ? { hideTicks: true, ...y } : { zero: offset !== "none", ...y }}
    >
      {draw}
    </ChartFrame>
  );
}
